mapper.select:
SELECT 
  FROM pay32_insure_pay
       INNER JOIN emp01_person ON emp01_person_id = pay32_person_id
 WHERE pay32_company_id = #{companyId}
   AND pay32_year LIKE #{year}
   AND pay32_insure_cd LIKE #{insureCode}
   AND pay32_person_id = #{personId}
 ORDER BY pay32_date, COALESCE(pay32_cnt, 0)

SELECT 
  FROM pay32_insure_pay
       INNER JOIN emp01_person ON emp01_person_id = pay32_person_id
 WHERE pay32_company_id = #{companyId}
   AND pay32_insure_pay_id = #{insurePayId}

mapper.delete:
DELETE FROM pay32_insure_pay
 WHERE pay32_company_id = #{companyId}
   AND pay32_insure_pay_id IN
#{id}
